package career.assistant.application.service;
import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.company.repository.CompanyRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime;
@Service public class ApplicationNotificationService {private final ApplicationRepository apps;private final CompanyRepository companies;private final JavaMailSender sender;private final boolean enabled;private final String username,to;public ApplicationNotificationService(ApplicationRepository a,CompanyRepository c,JavaMailSender s,@Value("${career.mail.enabled:false}")boolean e,@Value("${career.mail.username:}")String u,@Value("${career.mail.notification-to:sahana.gowda2227@gmail.com}")String t){apps=a;companies=c;sender=s;enabled=e;username=u;to=t;}
 @Transactional public boolean sendVerifiedSuccessOnce(Application a,String score){if(a.getStatus()!=ApplicationStatus.AUTO_APPLIED||a.getConfirmationId()==null||a.getConfirmationId().isBlank()||a.getNotificationSentAt()!=null)return false;if(!enabled)return false;SimpleMailMessage m=new SimpleMailMessage();if(!username.isBlank())m.setFrom(username);m.setTo(to);String company=companies.findById(a.getJob().getCompanyId()).map(c->c.getName()).orElse("Unknown company");m.setSubject("Application submitted: "+a.getJob().getTitle()+" at "+company);m.setText("Job: "+a.getJob().getTitle()+"\nCompany: "+company+"\nScore: "+score+"\nTimestamp: "+a.getSubmittedAt()+"\nSource: "+a.getApplicationUrl()+"\nConfirmation: "+a.getConfirmationId()+"\nResume version: "+a.getResumeVersionId());sender.send(m);a.setNotificationSentAt(OffsetDateTime.now());apps.save(a);return true;}}
